  <a class="skip-link" href="#main-content">Skip to main content</a>

  <div class="page-shell">
    <header>
      <p class="eyebrow">Support</p>
      <h1>Contact our team</h1>
      <p class="intro">Tell us how to reach you and a support specialist will follow up with the next best step.</p>
    </header>

    <main id="main-content">
      <section class="support-card" aria-labelledby="support-details-heading">
        <h2 id="support-details-heading">What to expect</h2>
        <p>Required fields are marked with an asterisk. Phone is optional, but it helps us call you back if that is easier.</p>
      </section>

      <section class="form-card" aria-labelledby="contact-form-heading">
        <h2 id="contact-form-heading">Send a support request</h2>
        <p class="required-note" aria-hidden="true">* Required field</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
              aria-invalid="false"
              placeholder="Jane Doe"
            >
            <p class="error-message" id="full-name-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
            <input
              id="email"
              name="email"
              type="email"
              autocomplete="email"
              inputmode="email"
              required
              aria-describedby="email-error"
              aria-invalid="false"
              placeholder="jane@example.com"
            >
            <p class="error-message" id="email-error" aria-live="polite"></p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number <span class="optional-note">(optional)</span></label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-helper phone-error"
              aria-invalid="false"
              placeholder="555-123-4567"
            >
            <p class="helper-text" id="phone-helper">Use 10 digits, optionally separated with spaces, hyphens, or parentheses. Example: 555-123-4567.</p>
            <p class="error-message" id="phone-error" aria-live="polite"></p>
          </div>

          <div class="button-row">
            <button type="submit">Submit support request</button>
            <p class="form-status" id="form-status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>
  </div>

  <script>
    const form = document.querySelector("#support-form");
    const statusMessage = document.querySelector("#form-status");
    const fields = {
      fullName: {
        input: document.querySelector("#full-name"),
        error: document.querySelector("#full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Enter your full name.";
        }
      },
      email: {
        input: document.querySelector("#email"),
        error: document.querySelector("#email-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

          if (!trimmedValue) {
            return "Enter your email address.";
          }

          return emailPattern.test(trimmedValue) ? "" : "Enter an email address in the format name@example.com.";
        }
      },
      phone: {
        input: document.querySelector("#phone"),
        error: document.querySelector("#phone-error"),
        validate(value) {
          const trimmedValue = value.trim();
          const phonePattern = /^(?:\+?1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}$/;

          if (!trimmedValue) {
            return "";
          }

          return phonePattern.test(trimmedValue) ? "" : "Enter a 10-digit phone number, such as 555-123-4567.";
        }
      }
    };

    function setFieldError(field, message) {
      field.error.textContent = message;
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldError(field, message);
      return !message;
    }

    Object.values(fields).forEach((field) => {
      field.input.addEventListener("input", () => {
        statusMessage.textContent = "";
        validateField(field);
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      let invalidField = null;

      Object.values(fields).forEach((field) => {
        const isValid = validateField(field);

        if (!isValid && !invalidField) {
          invalidField = field;
        }
      });

      if (invalidField) {
        statusMessage.textContent = "";
        invalidField.input.focus();
        return;
      }

      form.reset();
      Object.values(fields).forEach((field) => setFieldError(field, ""));
      statusMessage.textContent = "Thanks. Your support request is ready to send.";
    });
  </script>
</body>
</html>
